  function normalizeRoleValue(rawRole) {
    var normalized = String(rawRole || '').trim().toUpperCase().replace(/[\s-]+/g, '_');
    if (!normalized) {
      return '';
    }
    if (ROLE_OPTIONS.indexOf(normalized) >= 0) {
      return normalized;
    }
    var aliasKey = normalized.replace(/_/g, '');
    var aliases = {
      ADMIN: 'STATION_ADMIN',
      ADMINISTRATOR: 'STATION_ADMIN',
      STATIONADMIN: 'STATION_ADMIN',
      STATIONADMINISTRATOR: 'STATION_ADMIN',
      ADMINSTATION: 'STATION_ADMIN',
      SUPERADMIN: 'SUPER_ADMIN',
      TOURNAMENTMANAGER: 'TOURNAMENT_MANAGER',
      GAMEMANAGER: 'GAME_MANAGER',
      OPERATIONSMANAGER: 'MANAGER'
    };
    return aliases[aliasKey] || aliases[normalized] || normalized;
  }

  function normalizeConfig(raw) {
    var cfg = Object.assign({}, DEFAULTS, raw || {});
    if (!cfg.apiBaseUrl) {
      throw new Error('PHAB admin panel: apiBaseUrl is required');
    }
    cfg.apiBaseUrl = String(cfg.apiBaseUrl).replace(/\/+$/, '');
    cfg.userId = String(cfg.userId || 'admin-' + Math.random().toString(36).slice(2, 8));

    if (!Array.isArray(cfg.roles)) {
      cfg.roles = [];
    }
    cfg.roles = cfg.roles
      .map(function (role) {
        return normalizeRoleValue(role);
      })
      .filter(Boolean)
      .filter(function (role, index, list) {
        return list.indexOf(role) === index;
      });
    if (cfg.role && cfg.roles.indexOf(cfg.role) === -1) {
      var normalizedRole = normalizeRoleValue(cfg.role);
      if (normalizedRole && cfg.roles.indexOf(normalizedRole) === -1) {
        cfg.roles.unshift(normalizedRole);
      }
    }
    if (!Array.isArray(cfg.roleIds)) {
      cfg.roleIds = cfg.roles.slice();
    }
    cfg.roleIds = cfg.roleIds
      .map(function (roleId) { return String(roleId || '').trim(); })
      .filter(Boolean)
      .filter(function (roleId, index, list) { return list.indexOf(roleId) === index; });
    if (!Array.isArray(cfg.permissions)) {
      cfg.permissions = [];
    }
    cfg.permissions = cfg.permissions
      .map(function (permission) { return String(permission || '').trim(); })
      .filter(Boolean)
      .filter(function (permission, index, list) { return list.indexOf(permission) === index; });
    if (!Array.isArray(cfg.stationIds)) {
      cfg.stationIds = [];
    }
    if (!Array.isArray(cfg.connectorRoutes)) {
      cfg.connectorRoutes = [];
    }
    cfg.authToken = String(cfg.authToken || '').trim();
    if (!cfg.authToken) {
      try {
        cfg.authToken = String(window.localStorage.getItem('phab_admin_token') || '').trim();
      } catch (_error) {
        cfg.authToken = '';
      }
    }
    cfg.pollIntervalMs = Math.max(3000, Number(cfg.pollIntervalMs || DEFAULTS.pollIntervalMs));
    cfg.playerRatingAdminEnabled =
      cfg.playerRatingAdminEnabled === true ||
      String(cfg.playerRatingAdminEnabled || '').trim().toLowerCase() === 'true';
    cfg.subscriptionAdminEnabled =
      cfg.subscriptionAdminEnabled === true ||
      String(cfg.subscriptionAdminEnabled || '').trim().toLowerCase() === 'true';
    cfg.subscriptionTestRuntimeEnabled =
      cfg.subscriptionTestRuntimeEnabled === true ||
      String(cfg.subscriptionTestRuntimeEnabled || '').trim().toLowerCase() === 'true';
    cfg.notificationApiBaseUrl = String(cfg.notificationApiBaseUrl || '').replace(/\/+$/, '');
    cfg.notificationTenantKey = String(cfg.notificationTenantKey || 'local-padel').trim();
    cfg.notificationAppVersion = String(
      cfg.notificationAppVersion || DEFAULTS.notificationAppVersion
    ).trim();
    return cfg;
  }

