  function createListButton(title, meta, onClick, active) {
    var li = document.createElement('li');
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'phab-admin-list-btn' + (active ? ' phab-admin-list-btn-active' : '');
    btn.addEventListener('click', onClick);
    li.appendChild(btn);

    var titleEl = document.createElement('div');
    titleEl.className = 'phab-admin-list-title';
    titleEl.textContent = title;
    btn.appendChild(titleEl);

    var metaEl = document.createElement('div');
    metaEl.className = 'phab-admin-list-meta';
    metaEl.textContent = meta;
    btn.appendChild(metaEl);
    return li;
  }

  function isObject(value) {
    return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
  }

  function normalizeObject(value) {
    return isObject(value) ? value : {};
  }

  function normalizeArray(value) {
    return Array.isArray(value) ? value : [];
  }

  function normalizeMessageAttachments(value) {
    return normalizeArray(value)
      .map(function (item) {
        var attachment = normalizeObject(item);
        var type = String(attachment.type || '').trim().toUpperCase();
        var url = String(attachment.url || '').trim();
        if (type !== 'IMAGE' || !url) {
          return null;
        }
        return {
          id: String(
            attachment.id || 'attachment-' + Math.random().toString(36).slice(2, 10)
          ),
          type: 'IMAGE',
          url: url,
          name: String(attachment.name || '').trim() || undefined,
          mimeType: String(attachment.mimeType || '').trim() || undefined,
          size: Number.isFinite(Number(attachment.size))
            ? Math.max(0, Math.floor(Number(attachment.size)))
            : undefined
        };
      })
      .filter(Boolean)
      .slice(0, 10);
  }

  function createTextChip(text, tone) {
    var chip = document.createElement('span');
    chip.className =
      'phab-admin-chip' +
      (tone === 'alert'
        ? ' phab-admin-chip-alert'
        : tone === 'warn'
          ? ' phab-admin-chip-warn'
          : '');
    chip.textContent = String(text || '').trim();
    return chip;
  }

  function formatStationScope(stationIds) {
    if (!Array.isArray(stationIds) || stationIds.length === 0) {
      return 'все станции';
    }
    return stationIds.join(', ');
  }

  function formatConnectorScope(connectorRoutes) {
    if (!Array.isArray(connectorRoutes) || connectorRoutes.length === 0) {
      return 'все коннекторы';
    }
    return connectorRoutes.join(', ');
  }

  function formatRoleLabel(role) {
    if (role === 'SUPER_ADMIN') {
      return 'Суперадмин';
    }
    if (role === 'MANAGER') {
      return 'Управляющий';
    }
    if (role === 'STATION_ADMIN') {
      return 'Админ станции';
    }
    if (role === 'SUPPORT') {
      return 'Поддержка';
    }
    return role;
  }

  function hasRole(cfg, role) {
    return Boolean(cfg && Array.isArray(cfg.roles) && cfg.roles.indexOf(role) >= 0);
  }

  function hasAnyRole(cfg, roles) {
    return Array.isArray(roles)
      ? roles.some(function (role) {
          return hasRole(cfg, role);
        })
      : false;
  }

  function hasPermission(cfg, permission) {
    if (cfg && Array.isArray(cfg.permissions) && cfg.permissions.length > 0) {
      return cfg.permissions.indexOf('*') >= 0 || cfg.permissions.indexOf(permission) >= 0;
    }
    var legacyPermissions = {
      'dialogs:read': ['SUPER_ADMIN', 'SUPPORT', 'STATION_ADMIN', 'MANAGER', 'GAME_MANAGER', 'TOURNAMENT_MANAGER'],
      'dialogs:write': ['SUPER_ADMIN', 'SUPPORT', 'STATION_ADMIN', 'MANAGER'],
      'games:read': ['SUPER_ADMIN', 'SUPPORT', 'STATION_ADMIN', 'MANAGER', 'GAME_MANAGER', 'TOURNAMENT_MANAGER'],
      'games:write': ['SUPER_ADMIN', 'SUPPORT', 'MANAGER', 'GAME_MANAGER', 'TOURNAMENT_MANAGER'],
      'tournaments:read': ['SUPER_ADMIN', 'STATION_ADMIN', 'MANAGER', 'GAME_MANAGER', 'TOURNAMENT_MANAGER'],
      'tournaments:write': ['SUPER_ADMIN', 'MANAGER', 'GAME_MANAGER', 'TOURNAMENT_MANAGER'],
      'settings:read': ['SUPER_ADMIN', 'MANAGER'],
      'settings:write': ['SUPER_ADMIN', 'MANAGER'],
      'admin-users:read': ['SUPER_ADMIN', 'MANAGER'],
      'admin-users:write': ['SUPER_ADMIN'],
      'access:manage': ['SUPER_ADMIN'],
      'audit:read': ['SUPER_ADMIN', 'MANAGER'],
      'player-ratings:read': ['SUPER_ADMIN', 'MANAGER', 'SUPPORT', 'GAME_MANAGER', 'TOURNAMENT_MANAGER', 'STATION_ADMIN'],
      'player-ratings:write': ['SUPER_ADMIN'],
      'advertising:read': ['SUPER_ADMIN', 'MANAGER'],
      'advertising:write': ['SUPER_ADMIN', 'MANAGER'],
      'subscriptions:read': ['SUPER_ADMIN'],
      'subscriptions:catalog:write': ['SUPER_ADMIN'],
      'subscriptions:release:write': ['SUPER_ADMIN']
    };
    return hasAnyRole(cfg, legacyPermissions[permission] || []);
  }

  function canAccessSettings(cfg) {
    return hasPermission(cfg, 'settings:read') || hasPermission(cfg, 'admin-users:read');
  }

  function canAccessDialogs(cfg) {
    return hasPermission(cfg, 'dialogs:read');
  }

  function canAccessGames(cfg) {
    return hasPermission(cfg, 'games:read');
  }

  function canRequestGamePlayerRemoval(cfg) {
    return hasPermission(cfg, 'games:write') && hasAnyRole(cfg, [
      'SUPER_ADMIN',
      'GAME_MANAGER',
      'MANAGER'
    ]);
  }

  function canAccessTournaments(cfg) {
    return hasPermission(cfg, 'tournaments:read');
  }

  function canManageAdminUsers(cfg) {
    return hasPermission(cfg, 'admin-users:write');
  }

  function canManageRoles(cfg) {
    return hasPermission(cfg, 'access:manage');
  }

  function canReadAdminAudit(cfg) {
    return hasPermission(cfg, 'audit:read');
  }

  function isRestrictedStationAdminConfig(cfg) {
    if (!cfg || !Array.isArray(cfg.stationIds) || cfg.stationIds.length === 0) {
      return false;
    }
    return !hasPermission(cfg, 'settings:read') &&
      !hasPermission(cfg, 'games:write') &&
      !hasPermission(cfg, 'tournaments:write');
  }

  function canManageVivaSettings(cfg) {
    return hasPermission(cfg, 'settings:write');
  }

  function canToggleSystemMessages(cfg) {
    return hasAnyRole(cfg, ['SUPER_ADMIN', 'MANAGER', 'STATION_ADMIN']);
  }

  function canAccessCommunities(cfg) {
    return hasAnyRole(cfg, [
      'SUPER_ADMIN',
      'MANAGER',
      'SUPPORT',
      'GAME_MANAGER',
      'TOURNAMENT_MANAGER'
    ]);
  }

  function canAccessLaboratory(cfg) {
    return hasAnyRole(cfg, ['SUPER_ADMIN', 'MANAGER']);
  }

  function canAccessPlayerRatings(cfg) {
    return Boolean(cfg && cfg.playerRatingAdminEnabled) && hasPermission(cfg, 'player-ratings:read');
  }

  function canManagePlayerRatings(cfg) {
    return Boolean(cfg && cfg.playerRatingAdminEnabled) && hasPermission(cfg, 'player-ratings:write');
  }

  function canManageQuickReplySettings(cfg) {
    return hasPermission(cfg, 'settings:write');
  }

  function canManageAdvertisingSettings(cfg) {
    return hasPermission(cfg, 'advertising:write');
  }

  function canAccessSubscriptions(cfg) {
    return Boolean(cfg && cfg.subscriptionAdminEnabled) && hasPermission(cfg, 'subscriptions:read');
  }

  function canManageSubscriptionCatalog(cfg) {
    return canAccessSubscriptions(cfg) && hasPermission(cfg, 'subscriptions:catalog:write');
  }

  function canManageSubscriptionRelease(cfg) {
    return canAccessSubscriptions(cfg) && hasPermission(cfg, 'subscriptions:release:write');
  }

  function estimateDataUrlSize(dataUrl) {
    var normalized = String(dataUrl || '').trim();
    var commaIndex = normalized.indexOf(',');
    var body = commaIndex >= 0 ? normalized.slice(commaIndex + 1) : normalized;
    return Math.max(0, Math.round((body.length * 3) / 4));
  }

  function normalizeAdvertisingAdItem(value, index) {
    var ad = normalizeObject(value);
    var href = String(ad.href || '').trim();
    var imageUrl = String(ad.imageUrl || '').trim();
    var imageAssetId = String(ad.imageAssetId || '').trim();
    var squareImageUrl = String(ad.squareImageUrl || imageUrl).trim();
    var horizontalImageUrl = String(ad.horizontalImageUrl || imageUrl).trim();
    if (!href || !imageUrl) {
      return null;
    }
    return {
      id: String(ad.id || 'cabinet-home-ad-' + String(index + 1)).trim(),
      title: String(ad.title || '').trim(),
      badgeText: String(ad.badgeText || '').trim(),
      footerText: String(ad.footerText || '').trim(),
      href: href,
      imageUrl: imageUrl,
      imageAssetId: imageAssetId,
      squareImageUrl: squareImageUrl,
      squareImageAssetId: String(ad.squareImageAssetId || imageAssetId).trim(),
      horizontalImageUrl: horizontalImageUrl,
      horizontalImageAssetId: String(ad.horizontalImageAssetId || imageAssetId).trim(),
      isActive: ad.isActive !== false,
      position:
        Number.isFinite(Number(ad.position)) && Number(ad.position) >= 0
          ? Math.floor(Number(ad.position))
          : index,
      createdAt: String(ad.createdAt || '').trim(),
      updatedAt: String(ad.updatedAt || '').trim()
    };
  }

  function normalizeCabinetHomeAdvertisingSettings(value) {
    var source = normalizeObject(value);
    return {
      rotationEnabled: source.rotationEnabled === true,
      repeatEveryCards: normalizeIntSetting(source.repeatEveryCards, 4),
      updatedAt: String(source.updatedAt || '').trim(),
      updatedBy: String(source.updatedBy || '').trim(),
      ads: normalizeArray(source.ads)
        .map(normalizeAdvertisingAdItem)
        .filter(Boolean)
        .sort(function (left, right) {
          return left.position - right.position;
        })
    };
  }

  function normalizeAdvertisingInsights(value) {
    var source = normalizeObject(value);
    return {
      ads: normalizeArray(source.ads).map(function (item) {
        var insight = normalizeObject(item);
        return {
          adId: String(insight.adId || '').trim(),
          impressionCount: Math.max(0, Number(insight.impressionCount || 0)),
          clickCount: Math.max(0, Number(insight.clickCount || 0)),
          clickThroughRate: Math.max(0, Number(insight.clickThroughRate || 0)),
          clickedPhones: normalizeArray(insight.clickedPhones).map(function (entry) {
            var phone = normalizeObject(entry);
            return {
              phoneE164: String(phone.phoneE164 || '').trim(),
              clickCount: Math.max(0, Number(phone.clickCount || 0)),
              lastClickedAt: String(phone.lastClickedAt || '').trim()
            };
          }).filter(function (phone) { return Boolean(phone.phoneE164); })
        };
      }).filter(function (insight) { return Boolean(insight.adId); }),
      auditLog: normalizeArray(source.auditLog).map(function (entry) {
        var audit = normalizeObject(entry);
        return {
          id: String(audit.id || '').trim(),
          adId: String(audit.adId || '').trim(),
          actor: String(audit.actor || 'Система').trim(),
          action: String(audit.action || 'UPDATED').trim(),
          title: String(audit.title || '').trim(),
          changes: normalizeArray(audit.changes).map(function (change) {
            return String(change || '').trim();
          }).filter(Boolean),
          occurredAt: String(audit.occurredAt || '').trim()
        };
      }).filter(function (entry) { return Boolean(entry.id); })
    };
  }

  function normalizeMoneySetting(value, fallback) {
    var parsed = Number(String(value == null ? '' : value).trim().replace(',', '.'));
    if (!Number.isFinite(parsed) || parsed < 0) {
      return fallback;
    }
    return Math.round(parsed);
  }

  function normalizeIntSetting(value, fallback) {
    var parsed = Number(String(value == null ? '' : value).trim());
    if (!Number.isFinite(parsed) || parsed <= 0) {
      return fallback;
    }
    return Math.floor(parsed);
  }

  function normalizeStringListSetting(value, fallback) {
    var list = Array.isArray(value)
      ? value
      : typeof value === 'string'
        ? value.split(',')
        : [];
    var normalized = Array.from(
      new Set(
        list
          .map(function (item) {
            return String(item || '').trim();
          })
          .filter(Boolean)
      )
    );
    return normalized.length > 0 ? normalized : (fallback || []).slice();
  }

  function normalizeSplitPaymentPromoCampaign(value, fallback, index) {
    var source = normalizeObject(value);
    var defaults = fallback || DEFAULT_SPLIT_PAYMENT_PROMO_CONFIG.promos[0];
    var shareAmounts = normalizeObject(source.shareAmounts);
    return {
      id: String(source.id || defaults.id || ('promo-' + (index + 1))).trim(),
      title: String(source.title || defaults.title || ('Акция ' + (index + 1))).trim(),
      enabled: source.enabled === true || (source.enabled === undefined && defaults.enabled === true),
      expiresAt: String(source.expiresAt || '').trim(),
      stationIds: normalizeStringListSetting(source.stationIds, defaults.stationIds),
      stationNameIncludes: normalizeStringListSetting(
        source.stationNameIncludes,
        defaults.stationNameIncludes
      ),
      roomIds: normalizeStringListSetting(source.roomIds, defaults.roomIds),
      roomNameIncludes: normalizeStringListSetting(source.roomNameIncludes, defaults.roomNameIncludes),
      shareAmounts: {
        twoTeams: normalizeMoneySetting(shareAmounts.twoTeams, defaults.shareAmounts.twoTeams),
        fourPlayers: normalizeMoneySetting(shareAmounts.fourPlayers, defaults.shareAmounts.fourPlayers)
      },
      baseShareAmount: normalizeMoneySetting(source.baseShareAmount, defaults.baseShareAmount),
      vivaDirectionId: normalizeIntSetting(source.vivaDirectionId, defaults.vivaDirectionId),
      vivaExerciseTypeId: normalizeIntSetting(
        source.vivaExerciseTypeId,
        defaults.vivaExerciseTypeId
      )
    };
  }

  function normalizeSplitPaymentPromoSettings(value) {
    var source = normalizeObject(value);
    var defaults = DEFAULT_SPLIT_PAYMENT_PROMO_CONFIG;
    var rawPromos = Array.isArray(source.promos) && source.promos.length
      ? source.promos.slice(0, 2)
      : [source, defaults.promos[1]];
    var promos = rawPromos.map(function (promo, index) {
      return normalizeSplitPaymentPromoCampaign(
        promo,
        defaults.promos[index] || defaults.promos[0],
        index
      );
    });
    while (promos.length < 2) {
      promos.push(normalizeSplitPaymentPromoCampaign({}, defaults.promos[promos.length], promos.length));
    }
    var primary = promos[0];
    return {
      id: primary.id,
      title: primary.title,
      enabled: primary.enabled,
      expiresAt: primary.expiresAt,
      stationIds: primary.stationIds,
      stationNameIncludes: primary.stationNameIncludes,
      roomIds: primary.roomIds,
      roomNameIncludes: primary.roomNameIncludes,
      shareAmounts: primary.shareAmounts,
      baseShareAmount: primary.baseShareAmount,
      vivaDirectionId: primary.vivaDirectionId,
      vivaExerciseTypeId: primary.vivaExerciseTypeId,
      promos: promos,
      updatedAt: String(source.updatedAt || '').trim(),
      updatedBy: String(source.updatedBy || '').trim()
    };
  }

  function getQuickReplyTriggerLabel(triggerType) {
    var normalized = String(triggerType || '').trim().toUpperCase();
    for (var i = 0; i < QUICK_REPLY_TRIGGER_OPTIONS.length; i += 1) {
      if (QUICK_REPLY_TRIGGER_OPTIONS[i].value === normalized) {
        return QUICK_REPLY_TRIGGER_OPTIONS[i].label;
      }
    }
    return normalized || 'Триггер';
  }

  function getQuickReplyModeLabel(mode) {
    var normalized = String(mode || '').trim().toUpperCase();
    for (var i = 0; i < QUICK_REPLY_MODE_OPTIONS.length; i += 1) {
      if (QUICK_REPLY_MODE_OPTIONS[i].value === normalized) {
        return QUICK_REPLY_MODE_OPTIONS[i].label;
      }
    }
    return normalized || 'Подсказка';
  }

  function normalizeQuickReplyRule(rule) {
    var item = normalizeObject(rule);
    return {
      id: String(item.id || '').trim(),
      title: String(item.title || 'Быстрый ответ').trim(),
      triggerType: String(item.triggerType || 'KEYWORD').trim().toUpperCase(),
      triggerPhrase: String(item.triggerPhrase || '').trim(),
      triggerKeywords: normalizeArray(item.triggerKeywords)
        .map(function (keyword) {
          return String(keyword || '').trim();
        })
        .filter(Boolean),
      timeFrom: String(item.timeFrom || '').trim(),
      timeTo: String(item.timeTo || '').trim(),
      noClientReplyMinutes: Number(item.noClientReplyMinutes || 0),
      stationIds: normalizeArray(item.stationIds)
        .map(function (stationId) {
          return String(stationId || '').trim();
        })
        .filter(Boolean),
      mode: String(item.mode || 'SUGGESTION').trim().toUpperCase(),
      responseText: String(item.responseText || '').trim(),
      responseAttachments: normalizeMessageAttachments(item.responseAttachments),
      isActive: item.isActive !== false,
      usageCount: Math.max(0, Number(item.usageCount || 0)),
      lastUsedAt: String(item.lastUsedAt || '').trim(),
      createdAt: String(item.createdAt || '').trim(),
      updatedAt: String(item.updatedAt || '').trim()
    };
  }

  function normalizeQuickReplyUsageLog(entry) {
    var item = normalizeObject(entry);
    return {
      id: String(item.id || '').trim(),
      ruleId: String(item.ruleId || '').trim(),
      ruleTitle: String(item.ruleTitle || '').trim(),
      sourceType: String(item.sourceType || '').trim().toUpperCase(),
      dialogId: String(item.dialogId || '').trim(),
      connector: String(item.connector || '').trim(),
      stationId: String(item.stationId || '').trim(),
      clientRequestText: String(item.clientRequestText || '').trim(),
      systemResponseText: String(item.systemResponseText || '').trim(),
      usedByUserId: String(item.usedByUserId || '').trim(),
      mode: String(item.mode || '').trim().toUpperCase(),
      createdAt: String(item.createdAt || '').trim()
    };
  }

  function getQuickReplyStationScope(rule) {
    var stationIds = Array.isArray(rule && rule.stationIds) ? rule.stationIds : [];
    if (stationIds.length === 0) {
      return 'Все станции';
    }
    return stationIds
      .map(function (stationId) {
        if (stationId === QUICK_REPLY_STATION_UNASSIGNED) {
          return 'Без станции';
        }
        return stationId;
      })
      .join(', ');
  }

  function getQuickReplyTriggerDescription(rule) {
    var normalized = normalizeQuickReplyRule(rule);
    if (normalized.triggerType === 'EXACT_PHRASE') {
      return 'Фраза целиком: "' + normalized.triggerPhrase + '"';
    }
    if (normalized.triggerType === 'KEYWORD') {
      return 'Ключевое слово: "' + normalized.triggerPhrase + '"';
    }
    if (normalized.triggerType === 'KEYWORD_SET') {
      return 'Слова: ' + (normalized.triggerKeywords.join(', ') || '-');
    }
    if (normalized.triggerType === 'MESSAGE_TIME_RANGE') {
      return 'Время сообщения: ' +
        (normalized.timeFrom || '--:--') +
        ' — ' +
        (normalized.timeTo || '--:--');
    }
    if (normalized.triggerType === 'CLIENT_NO_REPLY_FOR') {
      return 'Нет ответа клиента ' +
        String(normalized.noClientReplyMinutes || 0) +
        ' мин';
    }
    if (normalized.triggerType === 'FIRST_CLIENT_MESSAGE') {
      return 'Первое сообщение клиента в диалоге';
    }
    if (normalized.triggerType === 'HAS_ATTACHMENT') {
      return 'Входящее сообщение с фото';
    }
    return getQuickReplyTriggerLabel(normalized.triggerType);
  }

  function createRichTextFragment(value) {
    var fragment = document.createDocumentFragment();
    var source = String(value || '');
    var pattern = /(\*\*[^*]+\*\*|\*[^*\n]+\*|\[[^\]]+\]\((https?:\/\/[^)\s]+)\))/g;
    var lastIndex = 0;
    var match;

    while ((match = pattern.exec(source)) !== null) {
      if (match.index > lastIndex) {
        fragment.appendChild(document.createTextNode(source.slice(lastIndex, match.index)));
      }

      var token = match[0];
      if (token.indexOf('**') === 0 && token.lastIndexOf('**') === token.length - 2) {
        var strong = document.createElement('strong');
        strong.textContent = token.slice(2, -2);
        fragment.appendChild(strong);
      } else if (token.indexOf('*') === 0 && token.lastIndexOf('*') === token.length - 1) {
        var em = document.createElement('em');
        em.textContent = token.slice(1, -1);
        fragment.appendChild(em);
      } else {
        var label = token.replace(/^\[/, '').replace(/\]\(https?:\/\/[^)\s]+\)$/, '');
        var hrefMatch = token.match(/\]\((https?:\/\/[^)\s]+)\)$/);
        var link = document.createElement('a');
        link.href = hrefMatch && hrefMatch[1] ? hrefMatch[1] : '#';
        link.target = '_blank';
        link.rel = 'noopener noreferrer';
        link.textContent = label || link.href;
        fragment.appendChild(link);
      }

      lastIndex = pattern.lastIndex;
    }

    if (lastIndex < source.length) {
      fragment.appendChild(document.createTextNode(source.slice(lastIndex)));
    }

    return fragment;
  }

  function appendRichTextContent(target, text) {
    target.appendChild(createRichTextFragment(text));
  }

  var DIALOG_FILTER_NO_STATION = '__NO_STATION__';
  var DIALOG_FILTER_NO_PHONE = '__NO_PHONE__';
  var STORAGE_KEY_INCLUDE_SERVICE_MESSAGES = 'phab_admin_include_service_messages';
  var STORAGE_KEY_MESSAGE_VIEW_MODE_LEGACY = 'phab_admin_message_view_mode';

  function loadStoredIncludeServiceMessages(fallbackValue) {
    try {
      var raw = String(window.localStorage.getItem(STORAGE_KEY_INCLUDE_SERVICE_MESSAGES) || '')
        .trim()
        .toLowerCase();
      if (raw === 'true' || raw === '1' || raw === 'yes' || raw === 'on') {
        return true;
      }
      if (raw === 'false' || raw === '0' || raw === 'no' || raw === 'off') {
        return false;
      }

      var legacyRaw = String(window.localStorage.getItem(STORAGE_KEY_MESSAGE_VIEW_MODE_LEGACY) || '')
        .trim()
        .toLowerCase();
      if (legacyRaw === 'service') {
        return true;
      }
      if (legacyRaw === 'regular') {
        return false;
      }
    } catch (_error) {
      // ignore storage errors
    }
    return fallbackValue === true;
  }

  function saveStoredIncludeServiceMessages(value) {
    try {
      window.localStorage.setItem(STORAGE_KEY_INCLUDE_SERVICE_MESSAGES, value ? 'true' : 'false');
      window.localStorage.removeItem(STORAGE_KEY_MESSAGE_VIEW_MODE_LEGACY);
    } catch (_error) {
      // ignore storage errors
    }
  }

